
from typing import Annotated, TypedDict

from langchain_core.documents import Document
from langchain_core.messages import AnyMessage
from langgraph.graph.message import add_messages


class ChatState(TypedDict):
    # Conversation history, preserved as messages are added
    messages: Annotated[list[AnyMessage], add_messages]

    # The original question from the user
    question: str

    # An improved version of the question for retrieval
    rewritten_question: str

    # Document chunks retrieved from FAISS
    documents: list[Document]

    # The final answer generated by the LLM
    generation: str

    # Number of retrieval retries attempted
    retry_count: int

    # Current route: greeting, document_question, or out_of_scope
    route: str

    retrieval_k: int
    
